/**
 * PICT model (#1188, census docs/PICT_CENSUS.md § S9): POST
 * /api/eduai/generate-questions (../../src/routes/eduai.js) forks on the
 * authenticated platform-role coverage, required-field validation (prompt; courseId OR
 * courseCode), numQuestions vs config.maxQuestions, and content-aware course
 * access — then, once admitted, forwards numQuestions/mcqRequiredChoiceCount/
 * distributions downstream unchanged (defaulted or clamped). One oracle
 * (tests/models/generate-questions.oracle.ts), one committed row table
 * (tests/models/generate-questions.cases.json, generated by
 * `npm run test:pict:gen` from tests/models/generate-questions.pict), and
 * one world-builder here, reusing tests/integration/eduaiRouteCoverage.integration.test.js's
 * established mocking (no DB / live Core; eduaiService and course-code /
 * courseId access resolution are mocked). Shared cases/oracle loading comes from
 * tests/helpers/pictModel.js; shared auth/settings/coreApiService mocks come
 * from tests/helpers/pictRouteMocks.js; the row-runner (describe.each +
 * request + status assertion) comes from tests/helpers/pictRouteRunner.js
 * (#1188).
 */
import { vi, it, expect, beforeEach, afterEach } from "vitest";
import { loadPictModel } from "../helpers/pictModel.js";
import { stubSessionUser } from "../helpers/pictRouteMocks.js";
import { describePictRoute } from "../helpers/pictRouteRunner.js";

const { mockFindCoursesByProjectedCode, mockEnrollments, mockCourseFindUnique, eduaiService } =
  vi.hoisted(() => ({
    mockFindCoursesByProjectedCode: vi.fn(),
    mockEnrollments: vi.fn(),
    mockCourseFindUnique: vi.fn(),
    eduaiService: { chat: vi.fn(), generateQuestions: vi.fn() },
  }));

// Dynamic imports (rather than a static import used directly in the factory)
// because vi.mock factories run before the module's own static imports are
// wired up — see tests/helpers/pictRouteMocks.js.
vi.mock("../../src/services/authService.js", async () => {
  const { mockAuthService } = await import("../helpers/pictRouteMocks.js");
  return mockAuthService();
});

vi.mock("../../src/config/settings.js", async () => {
  const { mockSettings } = await import("../helpers/pictRouteMocks.js");
  return mockSettings({ maxQuestions: 50 });
});

vi.mock("../../src/services/courseListService.js", () => ({
  findCoursesByProjectedCode: mockFindCoursesByProjectedCode,
}));

vi.mock("../../src/config/database.js", () => ({
  prisma: {
    course: {
      findUnique: (...args) => mockCourseFindUnique(...args),
      findFirst: (...args) => mockCourseFindUnique(...args),
      findMany: vi.fn().mockResolvedValue([]),
    },
  },
}));

vi.mock("../../src/services/coreApiService.js", async () => {
  const { mockCoreApiService } = await import("../helpers/pictRouteMocks.js");
  return mockCoreApiService(mockEnrollments);
});

vi.mock("../../src/services/eduaiService.js", () => ({
  default: eduaiService,
}));

const { default: app } = await import("../../src/app.js");

const { rows, oracle } = await loadPictModel("generate-questions");
const {
  generateQuestionsOracle,
  MAX_QUESTIONS,
  VALID_NUM_QUESTIONS,
  EXCEEDING_NUM_QUESTIONS,
  MCQ_INPUT,
  PROVIDED_DIFFICULTY_DISTRIBUTION,
  PROVIDED_REASONING_DISTRIBUTION,
} = oracle;

const INSTRUCTOR = {
  id: "inst-1",
  role: "INSTRUCTOR",
  email: "i@t.co",
  name: "I",
};
const STUDENT = { id: "stu-1", role: "STUDENT", email: "s@t.co", name: "S" };
const QM_COURSE_ID = 1;

function authAs(user) {
  stubSessionUser(user);
}

function accessibleCourseByCode() {
  const course = {
    id: QM_COURSE_ID,
    userId: INSTRUCTOR.id,
    coreCourseId: "cuid-core-course",
    code: null,
  };
  mockFindCoursesByProjectedCode.mockResolvedValue([course]);
  mockEnrollments.mockResolvedValue({
    enrollments: [{ studentId: INSTRUCTOR.id, role: "INSTRUCTOR", isActive: true }],
  });
  return course;
}

function accessibleCourseById() {
  const course = {
    id: QM_COURSE_ID,
    userId: INSTRUCTOR.id,
    coreCourseId: "cuid-core-course",
    code: null,
  };
  mockCourseFindUnique.mockResolvedValue(course);
  mockEnrollments.mockResolvedValue({
    enrollments: [{ studentId: INSTRUCTOR.id, role: "INSTRUCTOR", isActive: true }],
  });
  return course;
}

function denyCourseByCode() {
  mockFindCoursesByProjectedCode.mockResolvedValue([]);
}

function denyCourseById() {
  mockCourseFindUnique.mockResolvedValue({
    id: QM_COURSE_ID,
    userId: "other",
    coreCourseId: "cuid-core-course",
    code: null,
  });
  mockEnrollments.mockResolvedValue({ enrollments: [] });
}

beforeEach(() => vi.clearAllMocks());
afterEach(() => vi.restoreAllMocks());

function buildBody(row) {
  const body = {};
  if (row.PromptPresent === "yes") body.prompt = "Write questions about recursion";
  if (row.CourseIdPresent === "yes") body.courseId = QM_COURSE_ID;
  if (row.CourseCodePresent === "yes") body.courseCode = "COSC 101";
  if (row.NumQuestions === "valid") body.numQuestions = VALID_NUM_QUESTIONS;
  if (row.NumQuestions === "exceeds") body.numQuestions = EXCEEDING_NUM_QUESTIONS;
  const mcq = MCQ_INPUT[row.Mcq];
  if (mcq !== undefined) body.mcqRequiredChoiceCount = mcq;
  if (row.DifficultyDistribution === "provided")
    body.difficultyDistribution = PROVIDED_DIFFICULTY_DISTRIBUTION;
  if (row.ReasoningDistribution === "provided")
    body.reasoningDistribution = PROVIDED_REASONING_DISTRIBUTION;
  return body;
}

function setupRow(row) {
  authAs(row.Authorized === "yes" ? INSTRUCTOR : STUDENT);

  if (row.CourseIdPresent === "yes") {
    if (row.CourseAccess === "yes") accessibleCourseById();
    else denyCourseById();
  }

  if (row.CourseCodePresent === "yes") {
    if (row.CourseAccess === "yes") accessibleCourseByCode();
    else denyCourseByCode();
  } else {
    mockFindCoursesByProjectedCode.mockResolvedValue([]);
  }

  // When both identifiers are present, courseId wins — keep a code match
  // available so a mistaken code-path lookup would still succeed and fail
  // the preferredIdentifier assertion below.
  if (
    row.CourseIdPresent === "yes" &&
    row.CourseCodePresent === "yes" &&
    row.CourseAccess === "yes"
  ) {
    accessibleCourseById();
    accessibleCourseByCode();
  }

  eduaiService.generateQuestions.mockResolvedValue([{ id: "q1" }]);
  return buildBody(row);
}

async function verify({ expected }) {
  if (expected.status !== 200) return;
  const call = eduaiService.generateQuestions.mock.calls[0][0];
  expect(call.numQuestions).toBe(expected.forwarded.numQuestions);
  if (expected.forwarded.mcqRequiredChoiceCount === undefined) {
    expect(call).not.toHaveProperty("mcqRequiredChoiceCount");
  } else {
    expect(call.mcqRequiredChoiceCount).toBe(expected.forwarded.mcqRequiredChoiceCount);
  }
  expect(call.difficultyDistribution).toEqual(expected.forwarded.difficultyDistribution);
  expect(call.reasoningDistribution).toEqual(expected.forwarded.reasoningDistribution);

  if (expected.forwarded.preferredIdentifier === "courseId") {
    expect(mockCourseFindUnique).toHaveBeenCalled();
    expect(mockFindCoursesByProjectedCode).not.toHaveBeenCalled();
  } else {
    expect(mockFindCoursesByProjectedCode).toHaveBeenCalled();
  }
}

describePictRoute("generate-questions", {
  app,
  rows,
  method: "post",
  path: "/api/eduai/generate-questions",
  setupRow,
  oracle: generateQuestionsOracle,
  verify,
});

it("sanity: MAX_QUESTIONS matches the mocked config.maxQuestions", () => {
  expect(MAX_QUESTIONS).toBe(50);
});
